export function supabaseImageCopy(driveUrl: string): string | null {
  let url: URL;
  try { url = new URL(driveUrl); } catch { return null; }
  const id = url.hostname === "drive.google.com" ? (url.searchParams.get("id") || url.pathname.match(/\/file\/d\/([^/]+)/)?.[1]) : null;
  const path = id ? copies[id] : undefined;
  return path ? `https://yyzkqilrhnwfmsivnxnk.supabase.co/storage/v1/object/public/article-images/${path}` : null;
}
